namespace sv_26ce2481ff974a128a6a4f7e69ca1118;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@* Displays the step progress bar with clickable completed steps *@

<nav class="step-indicator" aria-label="Application progress">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var stepNumber = i + 1;
        var isCompleted = CompletedSteps.Contains(stepNumber);
        var isCurrent = stepNumber == CurrentStep;
        var cssClass = isCurrent ? "step current" : isCompleted ? "step completed" : "step future";

        <div class="@cssClass" @onclick="() => OnStepClick(stepNumber, isCompleted)">
            <span class="step-circle">
                @if (isCompleted && !isCurrent)
                {
                    <span class="checkmark">✓</span>
                }
                else
                {
                    @stepNumber
                }
            </span>
            <span class="step-label">@StepNames[stepIndex]</span>
        </div>

        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector @(isCompleted ? "completed" : "")"></div>
        }
    }
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter, EditorRequired]
    public int CurrentStep { get; set; }

    [Parameter, EditorRequired]
    public HashSet<int> CompletedSteps { get; set; } = new();

    [Parameter, EditorRequired]
    public EventCallback<int> OnStepSelected { get; set; }

    private async Task OnStepClick(int step, bool isCompleted)
    {
        if (isCompleted && step != CurrentStep)
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

