{"path": "/tmp/sv-26ce2481ff974a128a6a4f7e69ca1118/Components/Pages/Apply/WorkEntryForm.razor", "file_text": "<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" value="@Entry.Company"
                   @onchange="e => Update(Entry with { Company = e.Value?.ToString() ?? string.Empty })" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Entry.Title"
                   @onchange="e => Update(Entry with { Title = e.Value?.ToString() ?? string.Empty })" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => Update(Entry with { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>
        <div class="form-group">
            <label>
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent(bool.Parse(e.Value?.ToString() ?? "false"))" />
                Currently working here
            </label>
            @if (!IsCurrent)
            {
                <label>End Date</label>
                <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                       @onchange="e => Update(Entry with { EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!) })" />
            }
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description"
                  @onchange="e => Update(Entry with { Description = e.Value?.ToString() ?? string.Empty })"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public WorkEntry Entry { get; set; } = default!;

    [Parameter]
    public int Index { get; set; }

    [Parameter]
    public bool CanRemove { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<WorkEntry> OnEntryChanged { get; set; }

    [Parameter]
    public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null;

    private async Task Update(WorkEntry updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }

    private async Task ToggleCurrent(bool isCurrent)
    {
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        await OnEntryChanged.InvokeAsync(updated);
    }
}
"}

