{"file_text": "<section class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       CanRemove="@(Entries.Count > 1)"
                       OnEntryChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter]
    public List<WorkEntry>? InitialData { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<List<WorkEntry>> OnNext { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnBack { get; set; }

    private List<WorkEntry> Entries { get; set; } = new();
    private string? ErrorMessage { get; set; }

    protected override void OnInitialized()
    {
        if (InitialData is { Count: > 0 })
        {
            Entries = InitialData.ToList();
        }
        else
        {
            Entries = new List<WorkEntry> { CreateEmptyEntry() };
        }
    }

    private static WorkEntry CreateEmptyEntry() =>
        new(string.Empty, string.Empty, DateTime.Today, null, string.Empty);

    private void AddEntry() => Entries.Add(CreateEmptyEntry());

    private void RemoveEntry(int index) => Entries.RemoveAt(index);

    private void UpdateEntry(int index, WorkEntry updated) => Entries[index] = updated;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position requires at least a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }
}
