{"file_text": "<section class="step-content">
    <h2>References</h2>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="@References[index]"
                       Index="index"
                       CanRemove="@(References.Count > 2)"
                       OnReferenceChanged="r => UpdateReference(index, r)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter]
    public List<Reference>? InitialData { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<List<Reference>> OnNext { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnBack { get; set; }

    private List<Reference> References { get; set; } = new();
    private string? ErrorMessage { get; set; }

    protected override void OnInitialized()
    {
        if (InitialData is { Count: > 0 })
        {
            References = InitialData.ToList();
        }
        else
        {
            References = new List<Reference>
            {
                CreateEmptyReference(),
                CreateEmptyReference()
            };
        }
    }

    private static Reference CreateEmptyReference() =>
        new(string.Empty, string.Empty, string.Empty, string.Empty);

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(CreateEmptyReference());
    }

    private void RemoveReference(int index) => References.RemoveAt(index);

    private void UpdateReference(int index, Reference updated) => References[index] = updated;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Each reference requires at least a name, relationship, and email.";
                return;
            }
        }

        await OnNext.InvokeAsync(References);
    }
}
